begin;

-- SECURITY DEFINER functions in historical migrations use public as a bounded
-- search path. Prevent browser/database API roles from creating shadow objects
-- in that schema; migrations still run as the database owner.
revoke create on schema public from public, anon, authenticated;
grant usage on schema public to anon, authenticated, service_role;

-- Atomic, service-only rate-limit accounting. Application callers never receive
-- direct table access, and identifier values are one-way hashes generated by the server.
create or replace function public.consume_rate_limit(
  requested_identifier text,
  requested_route text,
  requested_limit integer,
  requested_window_start timestamptz
)
returns table(hits integer, blocked boolean)
language plpgsql
security definer
set search_path = pg_catalog, pg_temp
as $$
declare
  result_hits integer;
  result_blocked boolean;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'RATE_LIMIT_SERVICE_ROLE_REQUIRED' using errcode = '42501';
  end if;
  if requested_identifier is null or length(requested_identifier) < 16 or length(requested_identifier) > 180
     or requested_route is null or length(requested_route) < 2 or length(requested_route) > 120
     or requested_limit is null or requested_limit < 1 or requested_limit > 10000
     or requested_window_start is null then
    raise exception 'RATE_LIMIT_ARGUMENT_INVALID' using errcode = '22023';
  end if;

  insert into public.rate_limit_events(identifier, route, window_start, hits, blocked)
  values (requested_identifier, requested_route, requested_window_start, 1, false)
  on conflict (identifier, route, window_start) do update
    set hits = public.rate_limit_events.hits + 1,
        blocked = public.rate_limit_events.hits + 1 > requested_limit
  returning public.rate_limit_events.hits, public.rate_limit_events.blocked
  into result_hits, result_blocked;

  return query select result_hits, result_blocked;
end;
$$;

revoke all on function public.consume_rate_limit(text,text,integer,timestamptz) from public, anon, authenticated;
grant execute on function public.consume_rate_limit(text,text,integer,timestamptz) to service_role;

-- Canonical product history is client-readable only through scoped RLS. All
-- mutations stay behind audited RPC/service paths.
revoke all on table public.digital_observer_risk_evaluations from anon;
revoke all on table public.digital_observer_decision_intents from anon;
revoke all on table public.digital_observer_incident_verifications from anon;
revoke all on table public.digital_observer_feedback_revisions from anon;
revoke all on table public.observer_ground_truth_reviews from anon;
revoke all on table public.digital_observer_calibration_samples from anon;
revoke all on table public.digital_observer_calibration_recommendations from anon;
revoke all on table public.digital_observer_watch_rule_versions from anon;
revoke all on table public.digital_observer_watch_rule_evaluations from anon;

revoke insert, update, delete on table public.digital_observer_risk_evaluations from authenticated;
revoke insert, update, delete on table public.digital_observer_decision_intents from authenticated;
revoke insert, update, delete on table public.digital_observer_incident_verifications from authenticated;
revoke insert, update, delete on table public.digital_observer_feedback_revisions from authenticated;
revoke insert, update, delete on table public.observer_ground_truth_reviews from authenticated;
revoke insert, update, delete on table public.digital_observer_calibration_samples from authenticated;
revoke insert, update, delete on table public.digital_observer_calibration_recommendations from authenticated;
revoke insert, update, delete on table public.digital_observer_watch_rule_versions from authenticated;
revoke insert, update, delete on table public.digital_observer_watch_rule_evaluations from authenticated;

grant select on table public.digital_observer_risk_evaluations to authenticated;
grant select on table public.digital_observer_decision_intents to authenticated;
grant select on table public.digital_observer_incident_verifications to authenticated;
grant select on table public.digital_observer_feedback_revisions to authenticated;
grant select on table public.observer_ground_truth_reviews to authenticated;
grant select on table public.digital_observer_calibration_samples to authenticated;
grant select on table public.digital_observer_calibration_recommendations to authenticated;
grant select on table public.digital_observer_watch_rule_versions to authenticated;
grant select on table public.digital_observer_watch_rule_evaluations to authenticated;

-- A requester may not attach another family's child identifier to a privacy request.
drop policy if exists "privacy rights child ownership boundary" on public.privacy_rights_requests;
create policy "privacy rights child ownership boundary" on public.privacy_rights_requests
as restrictive for insert to authenticated
with check (
  child_id is null
  or public.is_admin()
  or public.can_parent_access_child(child_id)
  or (garden_id is not null and public.can_manage_garden(garden_id))
);

notify pgrst, 'reload schema';

commit;
